$files = Get-ChildItem -Path resources/views -Recurse -Filter *.blade.php; foreach ($file in $files) { $text = [IO.File]::ReadAllText($file.FullName); $newText = [regex]::Replace($text, "dark:text-(slate|green|blue|orange)-([456]00)", { param($m) $color = $m.Groups[1].Value; $shade = [int]$m.Groups[2].Value; if ($shade -eq 600) { $newShade = 400 } elseif ($shade -eq 500) { $newShade = 400 } elseif ($shade -eq 400) { $newShade = 300 } else { $newShade = $shade }; return "dark:text-$color-$newShade" }); if ($text -cne $newText) { [IO.File]::WriteAllText($file.FullName, $newText) } }
